def sum_of_scores(n: int, m: int) -> int:
    """ Calculate the sum of scores of all good sequences modulo 998244353.
    """
    if m == 1:
        return n % MOD

    # primes <= m
    def is_prime(x):
        if x < 2:
            return False
        for d in range(2, int(x**0.5)+1):
            if x % d == 0:
                return False
        return True
    primes = [p for p in range(2, m+1) if is_prime(p)]
    r = len(primes)
    d = 1 << r

    # exponents for each a
    exps = []
    for a in range(1, m+1):
        tmp = a
        e = [0]*r
        for i, p in enumerate(primes):
            cnt = 0
            while tmp % p == 0:
                tmp //= p
                cnt += 1
            e[i] = cnt
        exps.append(e)

    # O[mask]
    O = [0]*d
    for mask in range(d):
        s = 0
        if mask == 0:
            s = m  # each a contributes 1
        else:
            for e in exps:
                prod = 1
                # early break if any required prime exponent zero
                for i in range(r):
                    if (mask >> i) & 1:
                        if e[i] == 0:
                            prod = 0
                            break
                        prod *= e[i]
                s += prod
        O[mask] = s % MOD

    import numpy as np

    # Try to use numba for speed
    try:
        import numba
        has_numba = True
    except ImportError:
        has_numba = False

    if has_numba:
        # Build M as numpy array
        M = np.zeros((d, d), dtype=np.int64)
        for S in range(d):
            for T in range(d):
                if (T & ~S) == 0:
                    diff = S & ~T  # same as S ^ T when T subset S
                    M[S, T] = O[diff]
        # p = column sums of M = u^T M
        p_vec = np.sum(M, axis=0) % MOD  # shape (d,)

        @numba.njit
        def mat_mul_numba(A, B, MOD):
            n = A.shape[0]
            C = np.zeros((n, n), dtype=np.int64)
            for i in range(n):
                for k in range(n):
                    aik = A[i, k]
                    if aik == 0:
                        continue
                    for j in range(n):
                        C[i, j] = (C[i, j] + aik * B[k, j]) % MOD
            return C

        @numba.njit
        def vec_mat_mul_numba(vec, Mat, MOD):
            n = vec.shape[0]
            res = np.zeros(n, dtype=np.int64)
            for k in range(n):
                vk = vec[k]
                if vk == 0:
                    continue
                for j in range(n):
                    res[j] = (res[j] + vk * Mat[k, j]) % MOD
            return res

        max_log = n.bit_length()
        baseP = []
        baseR = []
        baseP.append(M)
        baseR.append(p_vec)
        for i in range(1, max_log):
            prevP = baseP[i-1]
            prevR = baseR[i-1]
            curP = mat_mul_numba(prevP, prevP, MOD)
            tmp = vec_mat_mul_numba(prevR, prevP, MOD)
            curR = (tmp + prevR) % MOD
            baseP.append(curP)
            baseR.append(curR)

        # identity matrix
        resP = np.eye(d, dtype=np.int64)
        resR = np.zeros(d, dtype=np.int64)

        bit = 0
        nn = n
        while nn > 0:
            if nn & 1:
                # res = res o base[bit]
                newP = mat_mul_numba(resP, baseP[bit], MOD)
                tmp2 = vec_mat_mul_numba(resR, baseP[bit], MOD)
                newR = (tmp2 + baseR[bit]) % MOD
                resP = newP
                resR = newR
            nn >>= 1
            bit += 1

        return int(resR[0] % MOD)
    else:
        # fallback pure python with sparsity optimisation
        # Build M as list of lists
        M_list = [[0]*d for _ in range(d)]
        for S in range(d):
            for T in range(d):
                if (T & ~S) == 0:
                    diff = S & ~T
                    M_list[S][T] = O[diff]

        # p vector column sums
        p_list = [0]*d
        for j in range(d):
            s = 0
            for i in range(d):
                s += M_list[i][j]
            p_list[j] = s % MOD

        # precompute subsets for each mask: list of sub-masks
        subsets = []
        for S in range(d):
            lst = []
            for T in range(d):
                if (T & ~S) == 0:
                    lst.append(T)
            subsets.append(lst)

        def mat_mul_list(A, B):
            C = [[0]*d for _ in range(d)]
            for i in range(d):
                # iterate k in subsets[i]
                for k in subsets[i]:
                    aik = A[i][k]
                    if aik == 0:
                        continue
                    # iterate j in subsets[k]
                    rowB = B[k]
                    # we loop over j's but check if rowB[j]==0 still many zeros? Keep filter
                    for j in subsets[k]:
                        bj = rowB[j]
                        if bj == 0:
                            continue
                        C[i][j] = (C[i][j] + aik * bj) % MOD
            return C

        def vec_mat_mul_list(vec, Mat):
            res = [0]*d
            for k in range(d):
                vk = vec[k]
                if vk == 0:
                    continue
                row = Mat[k]
                for j in subsets[k]:
                    bj = row[j]
                    if bj == 0:
                        continue
                    res[j] = (res[j] + vk * bj) % MOD
            return res

        max_log = n.bit_length()
        baseP_list = [M_list]
        baseR_list = [p_list]
        for i in range(1, max_log):
            prevP = baseP_list[i-1]
            prevR = baseR_list[i-1]
            curP = mat_mul_list(prevP, prevP)
            tmp = vec_mat_mul_list(prevR, prevP)
            curR = [(tmp[j] + prevR[j]) % MOD for j in range(d)]
            baseP_list.append(curP)
            baseR_list.append(curR)

        # identity
        resP = [[1 if i == j else 0 for j in range(d)] for i in range(d)]
        resR = [0]*d
        bit = 0
        nn = n
        while nn > 0:
            if nn & 1:
                newP = mat_mul_list(resP, baseP_list[bit])
                tmp2 = vec_mat_mul_list(resR, baseP_list[bit])
                newR = [(tmp2[j] + baseR_list[bit][j]) % MOD for j in range(d)]
                resP = newP
                resR = newR
            nn >>= 1
            bit += 1
        return resR[0] % MOD
